import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Group } from 'three/webgpu';
import { texture, uv, mix, vec3, smoothstep, uniform, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;

  const group = new Group();
  group.name = 'hub-collection-card-3';

  // --- Palette (spec-exact) ---
  const colors = config.intent?.visualSpec?.colors ?? {};
  const inkC = new THREE.Color(colors.ink ?? '#16161d');
  const paperC = new THREE.Color(colors.paper ?? '#e8ecf2');
  const accentC = new THREE.Color(colors.accent ?? '#ff2a38');
  const surfaceC = new THREE.Color(colors.surface ?? '#0b0b10');

  const ink = vec3(inkC.r, inkC.g, inkC.b);
  const paper = vec3(paperC.r, paperC.g, paperC.b);
  const accent = vec3(accentC.r, accentC.g, accentC.b);
  const surface = vec3(surfaceC.r, surfaceC.g, surfaceC.b);

  // --- Geometry: atlas region 512x320 -> 1.6:1 aspect ---
  const aspect = 512 / 320;
  const cardW = 1.92;
  const cardH = cardW / aspect; // 1.2

  const geo = new PlaneGeometry(cardW, cardH);

  // --- Texture (async) with 1x1 fallback so the node graph compiles immediately ---
  const fallback = new THREE.DataTexture(new Uint8Array([11, 11, 16, 255]), 1, 1, THREE.RGBAFormat);
  fallback.needsUpdate = true;
  const texUniform = uniform(fallback);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.wrapS = THREE.ClampToEdgeWrapping;
      tex.wrapT = THREE.ClampToEdgeWrapping;
      texUniform.value = tex;
    });
  }

  // --- Engineered gradient surface + subtle grain via TSL ---
  const mat = new MeshBasicNodeMaterial({ transparent: true });
  const st = uv();

  const gradT = smoothstep(float(0.0), float(1.0), st.y);
  const baseGrad = mix(surface, ink, gradT);
  // faint paper lift toward the top edge for engineered depth
  const topLift = mix(baseGrad, paper.mul(float(0.16)), smoothstep(float(0.72), float(1.0), st.y));
  // bottom warmth bias toward ink (grounds the card)
  const grounded = mix(topLift, ink.mul(float(1.05)), smoothstep(float(0.0), float(0.18), st.y));

  const grainTex = texture(texUniform, st);
  const grain = grainTex.r.mul(float(0.14));
  const finalColor = grounded.add(vec3(grain));

  const opacityU = uniform(0);
  mat.colorNode = finalColor.mul(opacityU);
  mat.transparent = true;
  mat.depthWrite = false;

  const mesh = new Mesh(geo, mat);
  mesh.renderOrder = 1;
  group.add(mesh);

  // --- Accent detail: thin signal-red rule along the bottom edge (<=10% frame accent) ---
  const rimGeo = new PlaneGeometry(cardW * 0.82, 0.012);
  const rimMat = new MeshBasicNodeMaterial({ transparent: true });
  rimMat.colorNode = accent.mul(float(0.85));
  rimMat.transparent = true;
  rimMat.depthWrite = false;
  const rim = new Mesh(rimGeo, rimMat);
  rim.position.set(0, -cardH / 2 + 0.03, 0.0015);
  rim.renderOrder = 2;
  group.add(rim);

  // --- Engineered corner ticks (paper hairlines) top-left + top-right ---
  const tickLen = 0.16;
  const tickThk = 0.006;
  const tickGeoH = new PlaneGeometry(tickLen, tickThk);
  const tickGeoV = new PlaneGeometry(tickThk, tickLen * 0.55);
  const tickMat = new MeshBasicNodeMaterial({ transparent: true });
  tickMat.colorNode = paper.mul(float(0.55));
  tickMat.transparent = true;
  tickMat.depthWrite = false;

  const tl = new Mesh(tickGeoH, tickMat);
  tl.position.set(-cardW / 2 + tickLen / 2 + 0.06, cardH / 2 - 0.06, 0.0015);
  tl.renderOrder = 2;
  const tr = new Mesh(tickGeoH, tickMat);
  tr.position.set(cardW / 2 - tickLen / 2 - 0.06, cardH / 2 - 0.06, 0.0015);
  tr.renderOrder = 2;
  group.add(tl, tr);

  // --- Entrance motion: rise-in + weighted-settle + fade (no linear easing) ---
  const tlAnim = gsap.timeline();
  tlAnim.from(group.position, { y: '+=0.4', duration: 0.7, ease: 'power3.out' }, 0);
  tlAnim.from(group.scale, { x: 0.96, y: 0.96, duration: 0.9, ease: 'power4.out' }, 0);
  tlAnim.to(opacityU, { value: 1, duration: 0.5, ease: 'power2.out' }, 0);

  // No interactions per spec; expose empty handlers surface for the adapter contract
  group.userData.handlers = {};

  // --- Cleanup ---
  group.userData.cleanup = () => {
    tlAnim.kill();
    geo.dispose();
    rimGeo.dispose();
    tickGeoH.dispose();
    tickGeoV.dispose();
    mat.dispose();
    rimMat.dispose();
    tickMat.dispose();
    fallback.dispose();
  };

  return group;
}
